  static final class TestFs extends AbstractCompressorArchiveFileSystem {
    TestFs(FileSystemProvider provider) {
      super(
          provider,
          URI.create("stubgz:/tmp/host.gz"),
          Path.of("host.gz"),
          "gzip",
          "payload",
          Path.of("payload.tmp"));
    }

