package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.net.URI;
import java.nio.file.FileSystemNotFoundException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class CompressorArchiveProviderSupportMutaGate12Test {

  @Test
  void pathFromUriResolvesArchiveKeyWithAndWithoutBang() {
    SingleEntryArchiveFormat format = SingleEntryArchiveFormat.GZIP;
    String prefix = format.uriSchemePrefix();
    List<URI> seen = new ArrayList<>();

    URI plain = URI.create(prefix + "/tmp/a.gz");
    assertThrows(
        FileSystemNotFoundException.class,
        () ->
            CompressorArchiveProviderSupport.pathFromUri(
                plain,
                format,
                key -> {
                  seen.add(key);
                  return null;
                }));

    URI withEntry = URI.create(prefix + "/tmp/a.gz!/inner/entry");
    assertThrows(
        FileSystemNotFoundException.class,
        () ->
            CompressorArchiveProviderSupport.pathFromUri(
                withEntry,
                format,
                key -> {
                  seen.add(key);
                  return null;
                }));

    URI expected = URI.create(prefix + Path.of("/tmp/a.gz").toAbsolutePath());
    assertEquals(2, seen.size());
    assertEquals(expected, seen.get(0));
    assertEquals(expected, seen.get(1));
  }
}

